#!/usr/bin/env python3
"""INTENT2 analysis (planned/INTENT2_PREREG.md). Risk formula and sizes copied unchanged from planned/risk2_analyze.py."""
import json, glob, math
R = [json.loads(l) for f in glob.glob('out/intent2/*.jsonl') for l in open(f) if l.strip()]
M, VOLS, HK = ('houston', 'dfw'), ('N1', 'N2', 'N2B'), ('A0', 'A2', 'M1', 'FLEX')
LV = {'L1': (3, 4), 'L2': (8, 13)}; K_RAD = math.sqrt(-2 * math.log(0.05)); K_VER = 1.96; WING = (0.65, 0.25); BIG = (1.5, 0.3)
Phi = lambda x: 0.5 * (1 + math.erf(x / math.sqrt(2)))
def band(d, W, s): return Phi((W - d) / s) - Phi((-W - d) / s) if s > 0 else (1.0 if abs(d) < W else 0.0)
size = lambda op: WING if op == 'wing' else BIG
def expected(row, lv):
    h95, v95 = LV[lv]; sh = math.sqrt(2) * h95 / K_RAD; sz = math.sqrt(2) * v95 / K_VER; p = 0.0
    for opA, opB, dperp, dz, dh, vrel in row['enc']: A, B = size(opA), size(opB); p += band(dperp, A[0] + B[0], sh) * band(dz, A[1] + B[1], sz)
    return p
LVL = {'N1': 'L1', 'N2': 'L2', 'N2B': 'L2'}
def rr(m, a, c): return [r for r in R if r['part'] == 'r' and r['metro'] == m and r['arm'] == a and r['check'] == c]
def rate(m, a, c, lv=None): x = rr(m, a, c); lv = lv or LVL[c]; return 1e5 * sum(expected(r, lv) for r in x) / sum(r['flightHours'] for r in x)
def cc(m, h, v): return [r for r in R if r['part'] == 'c' and r['metro'] == m and r['heights'] == h and r['vol'] == v]
def held(rows, op='all'):
    n = sum(r['cost'][op]['n'] for r in rows if op in r['cost']); return sum(r['cost'][op]['delayed'] + r['cost'][op]['cancelled'] for r in rows if op in r['cost']) / n if n else float('nan')
Hd = lambda m, h, v, op='all': held(cc(m, h, v), op)
OLD = {('houston', 'A2'): 0.929, ('dfw', 'A2'): 1.11, ('houston', 'M1'): 0.674, ('dfw', 'M1'): 0.58}
P = []
def chk(n, ok, t): P.append((n, ok, t)); print('PASS' if ok else 'FAIL', n, t)
chk('J1', all(Hd(m, 'A2', 'N1') < 0.10 for m in M), '; '.join(f'{m} A2 N1 {100 * Hd(m, "A2", "N1"):.1f} %' for m in M))
chk('J2', all(Hd(m, 'M1', 'N2') >= 0.5 * Hd(m, 'A2', 'N2') for m in M), '; '.join(f'{m} N2 M1 {100 * Hd(m, "M1", "N2"):.1f} vs A2 {100 * Hd(m, "A2", "N2"):.1f} %' for m in M))
chk('J3', all(Hd(m, 'FLEX', 'N2B') <= Hd(m, 'A2', 'N2B') for m in M), '; '.join(f'{m} N2B FLEX {100 * Hd(m, "FLEX", "N2B"):.1f} vs A2 {100 * Hd(m, "A2", "N2B"):.1f} %' for m in M))
chk('J4', all(rate(m, a, 'N2') < OLD[(m, a)] for m in M for a in ('A2', 'M1')), '; '.join(f'{m} {a} N2 {rate(m, a, "N2"):.3g} vs old V2 {OLD[(m, a)]}' for m in M for a in ('A2', 'M1')))
chk('J5', all(rate(m, a, 'N2B') <= 0.2 for m in M for a in HK), '; '.join(f'{m} {a} {rate(m, a, "N2B"):.3g}' for m in M for a in HK))
chk('J6', all(rate(m, 'FLEX', 'N2') <= rate(m, 'A2', 'N2') for m in M), '; '.join(f'{m} N2 FLEX {rate(m, "FLEX", "N2"):.3g} vs A2 {rate(m, "A2", "N2"):.3g}' for m in M))
npass = sum(1 for _, ok, _ in P if ok)
L = ['# INTENT2 results table (generated by planned/intent2_analyze.py)', '', f'{npass} of {len(P)} predictions passed. Runs: {len(R)}.', ''] + [f'- {"PASS" if ok else "FAIL"} {n}: {t}' for n, ok, t in P]
L += ['', '## Held share (windy hours, seeds 1-5)', '', '| Metro | Heights | Volume | Held | Wing | Zipline | Amazon | Cancelled | Moved (FLEX) |', '|---|---|---|---|---|---|---|---|---|']
for m in M:
    for h in HK:
        for v in VOLS:
            x = cc(m, h, v); n = sum(r['cost']['all']['n'] for r in x); c = sum(r['cost']['all']['cancelled'] for r in x); mv = sum(r['moved']['n'] for r in x)
            L.append(f'| {m} | {h} | {v} | {100 * held(x):.1f} % | {100 * held(x, "wing"):.1f} % | {100 * held(x, "zipline"):.1f} % | {100 * held(x, "amazon"):.1f} % | {100 * c / n:.1f} % | {100 * mv / n:.1f} % |')
L += ['', '## Expected collisions per 100,000 flight hours (still air, seeds 1-5), at the GPS level each volume is sized for', '', '| Metro | Heights | No check (L1 / L2) | N1 (L1) | N2 (L2) | N2B (L2) | Held in still air N1 / N2 / N2B |', '|---|---|---|---|---|---|---|']
for m in M:
    for a in HK:
        hs = ' / '.join(f'{100 * sum(r["held"] for r in rr(m, a, v)) / max(1, sum(r["checked"] for r in rr(m, a, v))):.1f} %' for v in VOLS)
        L.append(f'| {m} | {a} | {rate(m, a, "NONE", "L1"):.3g} / {rate(m, a, "NONE", "L2"):.3g} | {rate(m, a, "N1"):.3g} | {rate(m, a, "N2"):.3g} | {rate(m, a, "N2B"):.3g} | {hs} |')
open('planned/intent2_results_table.md', 'w').write('\n'.join(L) + '\n'); print(f'{npass} of {len(P)} passed')
